import { interpolate } from "remotion";
import type { SfxId } from "../schemas/videoPlan";

// Files generated by tools/audio/generate_audio_assets.py and synced into
// public/assets/ like every other asset. Record<SfxId, ...>: an sfx id added to
// the schema without a sound here is a compile error, not a silent scene.
export const SFX_PATHS: Record<SfxId, string> = {
  pop: "assets/sfx/pop.wav",
  whoosh: "assets/sfx/whoosh.wav",
  error: "assets/sfx/error.wav",
  success: "assets/sfx/success.wav",
  impact: "assets/sfx/impact.wav",
  click: "assets/sfx/click.wav",
};

const MUSIC_PATHS = {
  upbeat: "assets/music/upbeat.wav",
  calm: "assets/music/calm.wav",
} as const;

export type MusicMoodId = keyof typeof MUSIC_PATHS;

// The plan's musicMood is validated by the backend, but plans can also be
// hand-written (samples/); anything unknown falls back instead of failing.
export function resolveMusicPath(mood: string | null): string {
  const key = (mood ?? "").toLowerCase();
  // hasOwnProperty, not `in`: "toString" is "in" every object.
  return Object.prototype.hasOwnProperty.call(MUSIC_PATHS, key)
    ? MUSIC_PATHS[key as MusicMoodId]
    : MUSIC_PATHS.upbeat;
}

// The mix (CLAUDE.md section 13: speech stays dominant). Remotion volumes are
// linear gain. Calibrated by measurement (tools/audio/measure_mix.py on a real
// render): music at 0.1 sat only ~12 dB under the speech; 0.06 puts it ~16 dB
// under - inside the usual 15-20 dB for background music under a voice, still
// clearly audible in the pauses.
export const AUDIO_MIX = {
  voice: 1,
  music: 0.06,
  sfx: 0.35,
  musicFadeInSeconds: 1,
  musicFadeOutSeconds: 1.5,
} as const;

// Music volume at a given frame: fades in at the start and out at the end, so
// the video neither starts with a hard musical edge nor gets cut off mid-bar.
export function musicVolumeAt(frame: number, fps: number, durationInFrames: number): number {
  const fadeIn = Math.max(1, Math.round(AUDIO_MIX.musicFadeInSeconds * fps));
  const fadeOut = Math.max(1, Math.round(AUDIO_MIX.musicFadeOutSeconds * fps));
  const envelope = Math.min(
    interpolate(frame, [0, fadeIn], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }),
    interpolate(frame, [durationInFrames - fadeOut, durationInFrames], [1, 0], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }),
  );
  return AUDIO_MIX.music * envelope;
}
